script:
(function () {
  'use strict';
  // Roth 401(k) vs traditional 401(k), same deferral into either account at the start of each year.
  //   Both balances grow at the same return, so they are equal before tax.
  //   Roth after tax = balance (qualified withdrawals are tax-free).
  //   Traditional after tax = balance x (1 - retirement tax rate) + optional side account: the tax the
  //     traditional deferral saves each year (deferral x current rate) invested in a taxable account
  //     growing at return x (1 - tax rate on investment returns).
  //   Break-even retirement rate = side account / traditional balance (0% without the side account).
  // Employer matching money is pre-tax in both cases, so it is left out of the comparison.
  // Checked in Node (fake DOM, whole script): $10,000 a year at 6% for 35 years, start of year =
  //   $1,181,209 (annuity-due formula) in both accounts; at 22% now and 15% later with the savings not
  //   invested, traditional after tax = 85% of that; with 0% tax on side-account returns the side account
  //   is 22% of the 401(k) balance, so the break-even rate is exactly 22% (the textbook result);
  //   "maximum" uses $24,500 a year, $32,500 at 50-59 and 64+, $35,750 at 60-63.
  // ---- 2026 IRS limits (IRS Notice 2025-67, tax year 2026) -------------------------------------
  var LIMITS = { year: 2026, deferral: 24500, catchUp50: 8000, catchUp60to63: 11250 };
  // ------------------------------------------------------------------------------------------------

  function maxFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.deferral + LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.deferral + LIMITS.catchUp50;
    return LIMITS.deferral;
  }

  // p: age, retireAge, contribution, useMax, rate, taxNow, taxLater, investTax (decimals), invest (bool)
  function compare(p) {
    var years = p.retireAge - p.age, bal = 0, side = 0, total = 0, rows = [];
    var sideRate = p.rate * (1 - p.investTax);
    for (var y = 0; y < years; y++) {
      var c = p.useMax ? maxFor(p.age + y) : p.contribution;
      bal = (bal + c) * (1 + p.rate);
      if (p.invest) side = (side + c * p.taxNow) * (1 + sideRate);
      total += c;
      var trad = bal * (1 - p.taxLater) + side;
      rows.push({ age: p.age + y, c: c, roth: bal, tradGross: bal, trad: trad, side: side, diff: bal - trad });
    }
    var tradAfter = bal * (1 - p.taxLater) + side;
    return { roth: bal, tradGross: bal, tradAfter: tradAfter, side: side, total: total, diff: bal - tradAfter,
             breakEven: bal > 0 ? side / bal : NaN, rows: rows };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var age = num('rtAge'), retireAge = num('rtRetireAge'), contribution = num('rtContrib'), rate = num('rtRate'),
        taxNow = num('rtTaxNow'), taxLater = num('rtTaxLater'), investTax = num('rtInvestTax'),
        useMax = document.getElementById('rtMax').checked, invest = document.getElementById('rtInvest').checked;
    document.getElementById('rtContrib').disabled = useMax;
    var error = document.getElementById('rtError');
    var bad = [age, retireAge, rate, taxNow, taxLater, investTax].some(isNaN) || (!useMax && isNaN(contribution)) ||
              age !== Math.round(age) || retireAge !== Math.round(retireAge) || age < 16 || age > 99 ||
              retireAge <= age || retireAge > 100 || (!useMax && (contribution < 0 || contribution > LIMITS.deferral + LIMITS.catchUp60to63)) ||
              rate < -20 || rate > 30 || taxNow < 0 || taxNow > 70 || taxLater < 0 || taxLater > 70 || investTax < 0 || investTax > 70;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter whole-number ages from 16 to 99 with retirement above your age (up to 100), a contribution from $0 to ' +
                          fmt(LIMITS.deferral + LIMITS.catchUp60to63) + ', a return from -20 to 30% and tax rates up to 70%.';
      return;
    }
    var r = compare({ age: age, retireAge: retireAge, contribution: contribution, useMax: useMax, rate: rate / 100,
                      taxNow: taxNow / 100, taxLater: taxLater / 100, investTax: investTax / 100, invest: invest });
    var tie = Math.abs(r.diff) < 0.5;
    set('rtWinner', tie ? 'Even' : r.diff > 0 ? 'Roth 401(k)' : 'Traditional 401(k)');
    set('rtDiff', fmt(Math.abs(r.diff)));
    set('rtRoth', fmt(r.roth));
    set('rtTrad', fmt(r.tradAfter));
    set('rtTradGross', fmt(r.tradGross));
    set('rtTradTax', fmt(r.tradGross * taxLater / 100));
    set('rtSide', invest ? fmt(r.side) : 'Not invested');
    set('rtTotal', fmt(r.total));
    var first = useMax ? maxFor(age) : contribution;
    set('rtTakeHome', 'This year a ' + fmt(first) + ' deferral costs ' + fmt(first) + ' of take-home pay as Roth and ' +
        fmt(first * (1 - taxNow / 100)) + ' as traditional.');
    set('rtBreakEven', isFinite(r.breakEven) ? pct(r.breakEven) : '–');
    document.getElementById('rtBreakNote').hidden = !isFinite(r.breakEven);
    set('rtBreakNote', isFinite(r.breakEven) ? 'The Roth 401(k) comes out ahead if your tax rate in retirement is above ' +
        pct(r.breakEven) + (invest ? '.' : ', because the traditional tax savings are not invested.') : '');
    set('rtAgeLabel', 'At age ' + retireAge + ', after tax');
    var body = document.getElementById('rtSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, fmt(row.c), fmt(row.roth), fmt(row.trad), fmt(row.side), fmt(row.diff)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rtForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
